<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';
import {Bot,Database,Play,Pause,RefreshCw,ChevronLeft,ChevronRight,Check} from '@lucide/vue';
import {invoke} from '../uiPorts';
const props=defineProps<{projectId?:number}>();const emit=defineEmits<{confirmed:[]}>();
type Item={key:string;kind:string;target:string;assetCount:number;state:string;advice:string;confidence:number;reason:string;queueReason?:string;decision:string;revision:number;evidence:{domains:string[];companies:string[];subjectOrganizations:string[];organizationHints?:string[];icpOrganizations?:string[];sources:string[];exampleAssetIds:number[];quarantinedAssets:number;ambiguousIdentity:boolean;evidenceTruncated:boolean}};
type ReviewRun={id:string;organization:string;status:string;totalAssets:number;processedAssets:number;cursor:number;maxId:number;groups:number;counts:Record<string,number>;queueCounts:Record<string,number>;manualCounts:Record<string,number>;model:string;requests:number;inputTokens:number;outputTokens:number;unknownRequests:number;estimatedUsage:boolean;estimatedBatches:number;reason:string};
type View={run:ReviewRun|null;items:Item[];total:number;roots?:string[]};
const organization=ref(''),includeIsolated=ref(true),data=ref<View>(),filter=ref('actionable'),search=ref(''),page=ref(1),busy=ref(false),reading=ref(false),error=ref(''),notice=ref('');
const selectedHosts=ref<string[]>([]),scopeConsent=ref(false);
let generation=0,sequence=0,disposed=false,timer:ReturnType<typeof setTimeout>|undefined,searchTimer:ReturnType<typeof setTimeout>|undefined;
const run=computed(()=>data.value?.run),running=computed(()=>!!run.value&&['preparing','analyzing','pausing'].includes(run.value.status));
const pages=computed(()=>Math.max(1,Math.ceil((data.value?.total||0)/30)));
const progress=computed(()=>!run.value?.totalAssets?0:Math.min(100,Math.round(run.value.processedAssets/run.value.totalAssets*100)));
const remaining=computed(()=>run.value?.queueCounts?.pending||0);
const reviewed=computed(()=>['retain','review','exclude','evidence','conflict'].reduce((sum,key)=>sum+(run.value?.counts[key]||0),0));
const reviewProgress=computed(()=>!run.value?.groups?0:Math.min(100,reviewed.value/run.value.groups*100));
const statuses:Record<string,string>={preparing:'正在整理本地证据',ready:'等待 AI 审阅',analyzing:'AI 分批审阅中',pausing:'正在暂停',paused:'已暂停，可继续',completed:'可分析证据已处理',interrupted:'已中断，可继续'};
const labels:Record<string,string>={retain:'相关候选',review:'证据冲突，待复核',conflict:'证据冲突，待复核',evidence:'待补证，无需逐条审核',deferred:'本地待补证，未调用 AI',exclude:'建议无关，不参与补查',pending:'尚未分析',analyzing:'本批分析中',unknown:'技术错误，未自动重试'};
const queue=computed(()=>run.value?.queueCounts||{}),manual=computed(()=>run.value?.manualCounts||{});
function schedule(g=generation){clearTimeout(timer);if(!disposed&&g===generation&&running.value)timer=setTimeout(()=>void load(false,g),1500);}
async function load(reset=false,g=generation){
 const projectId=props.projectId,seq=++sequence;if(!projectId||disposed||g!==generation)return;if(reset)page.value=1;reading.value=true;
 try{const view=await invoke<View>('seed_review_status',{projectId,filter:filter.value,page:page.value,search:search.value.trim()});if(disposed||g!==generation||seq!==sequence)return;data.value=view;if(!organization.value.trim()&&view.run)organization.value=view.run.organization;}
 catch(e){if(g===generation&&seq===sequence)error.value=String(e);}
 finally{if(g===generation&&seq===sequence){reading.value=false;schedule(g);}}
}
async function control(action:'prepare'|'start'|'pause'|'triage',maxBatches=0){
 const projectId=props.projectId,g=generation,localResume=action==='start'&&!!run.value&&run.value.cursor<run.value.maxId;if(!projectId||busy.value||action==='prepare'&&!organization.value.trim())return;busy.value=true;error.value='';notice.value='';
 try{await invoke('control_seed_review',{input:{projectId,action,runId:run.value?.id,organization:organization.value.trim(),includeIsolated:includeIsolated.value,maxBatches}});if(disposed||g!==generation)return;if(action==='prepare'){filter.value='actionable';page.value=1;selectedHosts.value=[];scopeConsent.value=false;}await load(false,g);notice.value=action==='triage'?'本地队列已分流，原有模型结果和人工结论保留；没有调用模型或 Hunter。':action==='prepare'?'本地整理已启动，不联网，不消耗测绘积分。':action==='pause'?'已请求暂停，已完成结果保留。':localResume?'已继续本地整理，不联网，不消耗模型 Token 或测绘积分。':maxBatches?'先审一批，保存后暂停；核对质量后可继续全量。':'已开始分批 AI 审阅，可随时暂停；没有调用 Hunter。';}
 catch(e){if(g===generation)error.value=String(e);}
 finally{if(g===generation)busy.value=false;}
}
async function decide(item:Item,decision:string){const projectId=props.projectId,g=generation;if(!projectId||busy.value||!run.value)return;busy.value=true;error.value='';try{await invoke('decide_seed_review',{input:{projectId,runId:run.value.id,key:item.key,expectedRevision:item.revision,decision}});if(disposed||g!==generation)return;await load(false,g);notice.value='审核结论已保存；没有恢复、删除资产，也没有改变探测范围。';}catch(e){if(g===generation)error.value=String(e);}finally{if(g===generation)busy.value=false;}}
async function confirmScope(){const projectId=props.projectId,g=generation;if(!projectId||!run.value||busy.value||!scopeConsent.value||!selectedHosts.value.length)return;busy.value=true;error.value='';try{await invoke('confirm_seed_review_scope',{input:{projectId,runId:run.value.id,hosts:[...selectedHosts.value],expectedRoots:data.value?.roots||[],userConfirmed:true}});if(disposed||g!==generation)return;selectedHosts.value=[];scopeConsent.value=false;await load(false,g);notice.value='所选域名范围已保存。尚未启动主动探测或 Hunter；证书精确查询仍要通过同证书证据校验。';emit('confirmed');}catch(e){if(g===generation)error.value=String(e);}finally{if(g===generation)busy.value=false;}}
function query(){clearTimeout(searchTimer);const g=generation;searchTimer=setTimeout(()=>void load(true,g),250);}
watch(filter,()=>{void load(true);});
watch(()=>props.projectId,()=>{++generation;++sequence;clearTimeout(timer);clearTimeout(searchTimer);data.value=undefined;organization.value='';search.value='';page.value=1;filter.value='actionable';busy.value=false;error.value='';notice.value='';selectedHosts.value=[];scopeConsent.value=false;if(props.projectId)void load();},{immediate:true});
onUnmounted(()=>{disposed=true;++generation;clearTimeout(timer);clearTimeout(searchTimer);});
</script>
<template>
<section class="seed-review-workbench" data-testid="seed-review-workbench">
 <header><div><h3><Bot :size="18"/>AI 批量审阅证书与域名</h3><p>本地全量整理 → 按证书身份与域名组去重 → AI 分批给建议 → 人工确认范围 → 精确补查。</p></div><button class="button ghost compact" :disabled="busy||reading" @click="load()"><RefreshCw :size="14"/>刷新</button></header>
 <p v-if="!projectId">请先选择工作空间。</p>
 <template v-else>
  <div class="seed-review-setup"><label class="field"><span>明确的目标单位或业务范围</span><input v-model="organization" maxlength="240" placeholder="例如：中国移动集团及其下属单位；可补充确定的单位别名" :disabled="busy||running"/></label><button class="button secondary" :disabled="busy||running||!organization.trim()" data-seed-review-action="prepare" @click="control('prepare')"><Database :size="15"/>{{run?'重新整理全量证据':'整理全量本地证据'}}</button></div>
  <label class="seed-review-check"><input v-model="includeIsolated" type="checkbox" :disabled="busy||running"/>包含隔离区和回收记录，只读提取证据，不自动恢复资产</label>
  <p class="helper">本地整理不联网；AI 只接收域名、证书身份、Subject 单位及有限的单位/来源摘要，不发送 Key、页面或完整证书。按当前模型计费，显示调用和 Token 用量；不消耗 Hunter 积分。</p>
  <section v-if="run" class="seed-review-progress" role="status"><div><strong>{{statuses[run.status]||run.status}}</strong><span>任务单位：{{run.organization}}</span></div><p>已整理 {{run.processedAssets.toLocaleString()}} / {{run.totalAssets.toLocaleString()}} 条资产 · 去重后 {{run.groups.toLocaleString()}} 组证据 · 预计约 {{run.estimatedBatches}} 批</p><label class="seed-progress-label">本地证据整理<progress :value="progress" max="100"/></label><label v-if="run.groups" class="seed-progress-label">AI 有效审阅 {{reviewed.toLocaleString()}} / {{run.groups.toLocaleString()}} 组 · 本地待补证 {{run.counts.deferred||0}} 组<progress :value="reviewProgress" max="100"/></label><div class="seed-review-counts"><button @click="filter='retain'">相关候选 {{queue.retain||0}}</button><button class="uncertain" @click="filter='conflict'">证据冲突 {{queue.conflict||0}}</button><button @click="filter='exclude'">建议无关 {{queue.exclude||0}}</button><button @click="filter='evidence'">待补证 {{queue.evidence||0}}</button><button @click="filter='errors'">技术错误 {{queue.unknown||0}}</button><button @click="filter='pending'">尚未分析 {{queue.pending||0}}</button></div><p class="helper">人工已认可 {{manual.accepted||0}} · 已排除 {{manual.rejected||0}}，均已移出待办。待补证和建议无关不要求逐条审核；相关候选也不等于已确认归属。</p><p>{{run.reason}}</p><p class="helper">{{run.model||'尚未调用模型'}} · 请求 {{run.requests}} 次 · 输入 {{run.inputTokens.toLocaleString()}} / 输出 {{run.outputTokens.toLocaleString()}} Token{{run.estimatedUsage?'（包含估算）':''}}{{run.unknownRequests?` · ${run.unknownRequests} 次请求计费未知`:''}}。未知请求不会自动重发。</p>
   <div class="seed-review-actions"><button v-if="!running" class="button ghost" :disabled="busy||run.cursor<run.maxId" @click="control('triage')">整理待办队列（本地）</button><button v-if="!running&&remaining" class="button primary" :disabled="busy||run.cursor<run.maxId" data-seed-review-action="start" @click="control('start')"><Play :size="15"/>继续 AI 全量审阅</button><button v-if="!running&&remaining" class="button ghost" :disabled="busy||run.cursor<run.maxId" data-seed-review-action="sample" @click="control('start',1)">先试审一批</button><button v-if="!running&&run.cursor<run.maxId" class="button primary" :disabled="busy" @click="control('start')">继续本地整理</button><button v-if="running" class="button ghost" :disabled="busy||run.status==='pausing'" data-seed-review-action="pause" @click="control('pause')"><Pause :size="15"/>暂停并保留进度</button></div>
  </section>
  <template v-if="run">
   <div class="seed-review-filters"><label><span>审阅队列</span><select v-model="filter"><option value="actionable">待确认（相关候选 / 证据冲突）</option><option value="retain">相关候选</option><option value="conflict">证据冲突，待复核</option><option value="evidence">待补证（无需逐条审核）</option><option value="errors">技术错误（未自动重试）</option><option value="exclude">建议无关</option><option value="all">全部证据组</option><option value="pending">尚未分析</option><option value="accepted">人工认可关联</option><option value="rejected">人工排除</option></select></label><input v-model="search" placeholder="搜索域名、指纹或单位" @input="query"/></div>
   <p class="helper">AI 建议不是授权。认可关联只保存你的审核意见；从证据中勾选域名并在下方明确确认，才会加入探测范围。只有相关候选和证据冲突列入待确认。建议无关不参与补查；待补证暂存，不要求逐条人工审核。缺少指纹不会强制改变相关性建议。</p>
   <div class="seed-review-items"><article v-for="item in data?.items" :key="item.key"><div class="seed-review-item-title"><strong>{{item.kind==='certificate'?'证书 SHA-256':item.kind==='certificate_metadata'?'未绑定指纹的证书名称':'域名组（不是授权根域）'}}</strong><span class="seed-advice" :data-advice="item.state==='done'?item.advice:item.state">{{labels[item.state==='done'?item.advice:item.state]||item.state}}</span><small>人工：{{item.decision==='accepted'?'认可关联':item.decision==='rejected'?'已排除':'未审核'}}</small></div><code>{{item.kind==='certificate_metadata'?item.evidence.domains.join('、'):item.target}}</code><p>{{item.queueReason||item.reason||'等待本地整理或模型审阅；不会进入 Hunter。'}}</p><small>{{item.assetCount}} 条资产 · 示例 #{{item.evidence.exampleAssetIds.join('、')}} · 隔离/回收 {{item.evidence.quarantinedAssets}} 条{{item.evidence.evidenceTruncated?' · 证据示例有截断':''}}</small><details><summary>查看证据并选择候选域名（{{item.evidence.domains.length}}）</summary><p>叶证书 Subject Organization：{{item.evidence.subjectOrganizations.join('、')||'未取得'}}</p><p>采集标签 / 未绑定单位线索（不是备案主体）：{{[...item.evidence.companies,...(item.evidence.organizationHints||[])].join('、')||'无'}}</p><div class="seed-domain-options"><label v-for="domain in item.evidence.domains" :key="domain"><input v-model="selectedHosts" type="checkbox" :value="domain" :disabled="busy||(data?.roots||[]).includes(domain)"/><code>{{domain}}</code><small v-if="(data?.roots||[]).includes(domain)">已在范围</small></label></div><p>提供商备案单位：{{(item.evidence.icpOrganizations||[]).join('、')||'未取得'}}</p><p v-if="item.queueReason">旧版原始记录：{{item.reason}}</p><p>证据来源：{{item.evidence.sources.join(' / ')}}</p></details><div class="seed-review-item-actions"><button class="button ghost compact" :disabled="busy||item.decision==='accepted'" @click="decide(item,'accepted')">认可关联</button><button class="button ghost compact" :disabled="busy||item.decision==='rejected'" @click="decide(item,'rejected')">人工排除</button><button v-if="item.decision!=='pending'" class="button ghost compact" :disabled="busy" @click="decide(item,'pending')">撤销审核</button></div></article></div>
   <p v-if="!data?.items.length&&!reading" class="helper">当前队列没有记录。待补证和技术错误已单独列出，无需逐条确认；可切换筛选查看。</p>
   <footer><span>{{data?.total.toLocaleString()}} 组 · {{page}} / {{pages}} 页</span><button class="button ghost compact" :disabled="reading||page<=1" @click="page--;load()"><ChevronLeft :size="14"/>上一页</button><button class="button ghost compact" :disabled="reading||page>=pages" @click="page++;load()">下一页<ChevronRight :size="14"/></button></footer>
   <div v-if="selectedHosts.length" class="seed-scope-confirm"><strong>准备加入范围：{{selectedHosts.length}} 个实际观察域名</strong><p>{{selectedHosts.join('、')}}</p><label class="seed-review-check"><input v-model="scopeConsent" type="checkbox" :disabled="busy"/>我已核对所选域名及其子域与目标单位相关，并允许后续在此范围探测；共享平台已限定具体租户。</label><button class="button primary" :disabled="busy||!scopeConsent||selectedHosts.length>50" data-seed-review-action="confirm" @click="confirmScope"><Check :size="15"/>确认保存所选范围</button><p class="helper">每次最多50项；只保存范围，不立即查询 Hunter、探测或确认资产归属。</p></div>
  </template>
  <p v-if="notice" class="seed-review-notice" role="status">{{notice}}</p><p v-if="error" class="form-error" role="alert">{{error}}</p>
 </template>
</section>
</template>
<style scoped>
.seed-review-workbench{border:1px solid var(--line);border-radius:10px;padding:18px;background:var(--app-surface,#fff);margin-bottom:18px;font-size:12px;line-height:1.65}.seed-review-workbench>header{display:flex;justify-content:space-between;gap:16px;align-items:start}.seed-review-workbench h3{display:flex;gap:8px;align-items:center;margin:0;font-size:15px}.seed-review-workbench header p,.helper{color:var(--muted);font-size:12px;margin:7px 0 12px}.seed-review-setup{display:flex;align-items:end;gap:12px;margin:14px 0 8px}.seed-review-setup .field{flex:1;min-width:0;display:flex;flex-direction:column;gap:6px}.seed-review-setup input,.seed-review-filters input,.seed-review-filters select{box-sizing:border-box;min-height:36px;font:inherit;color:inherit;border:1px solid var(--line,#ddd);border-radius:7px;background:var(--app-surface,#fff);padding:7px 10px;box-shadow:none}.seed-review-filters select{appearance:none;-webkit-appearance:none;height:36px;min-width:180px;padding-right:30px;background-image:linear-gradient(45deg,transparent 50%,#777 50%),linear-gradient(135deg,#777 50%,transparent 50%);background-position:calc(100% - 15px) 50%,calc(100% - 10px) 50%;background-size:5px 5px;background-repeat:no-repeat}.seed-progress-label{display:flex;flex-direction:column;gap:4px;margin:8px 0;color:var(--muted);font-size:11px}.seed-review-check{display:flex;align-items:start;gap:8px;font-size:12px}.seed-review-check input,.seed-domain-options input{width:16px;height:16px;min-height:0;margin:3px 0;flex:0 0 16px;accent-color:var(--blue)}.seed-review-progress{padding:14px;margin:14px 0;border:1px solid var(--line);border-radius:8px;background:var(--app-bg,#fafafa)}.seed-review-progress>div:first-child{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.seed-review-progress progress{width:100%;height:7px;accent-color:var(--blue)}.seed-review-counts{display:flex;flex-wrap:wrap;gap:16px;margin:10px 0}.uncertain{color:#956116}.seed-review-counts button{border:0;background:transparent;color:inherit;font:inherit;padding:0;cursor:pointer}.seed-review-counts button:hover{text-decoration:underline}.seed-review-actions,.seed-review-item-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}.seed-review-filters{display:flex;gap:12px;align-items:end;margin:18px 0 8px}.seed-review-filters label{display:flex;flex-direction:column;gap:5px}.seed-review-filters input{flex:1;min-width:100px}.seed-review-items{max-height:560px;overflow:auto;overscroll-behavior:contain;border:1px solid var(--line);border-radius:8px}.seed-review-items article{padding:14px;border-bottom:1px solid var(--line)}.seed-review-items article:last-child{border-bottom:0}.seed-review-item-title{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.seed-review-item-title small{margin-left:auto;color:var(--muted)}.seed-review-items code,.seed-scope-confirm p{overflow-wrap:anywhere;white-space:normal}.seed-advice{padding:1px 6px;border-radius:4px;background:#f1f2f3;color:#646b72}.seed-advice[data-advice=review],.seed-advice[data-advice=conflict]{background:#fff4dd;color:#8c601d}.seed-advice[data-advice=retain]{background:#e8f5ee;color:#26764e}.seed-review-items details{margin:9px 0}.seed-review-items summary{cursor:pointer;color:var(--muted)}.seed-review-items details p{margin:6px 0;font-size:11px;color:var(--muted)}.seed-domain-options{display:flex;flex-direction:column;gap:5px;max-height:180px;overflow:auto}.seed-domain-options label{display:flex;gap:7px;align-items:start}.seed-review-workbench footer{display:flex;gap:8px;justify-content:flex-end;align-items:center;margin-top:10px}.seed-review-workbench footer>span{margin-right:auto;color:var(--muted)}.seed-scope-confirm{position:sticky;bottom:0;padding:14px;margin-top:14px;background:var(--app-surface,#fff);border:1px solid #b9d4ef;border-radius:8px;box-shadow:0 3px 12px #00000009}.seed-scope-confirm p{max-height:90px;overflow:auto;font-size:11px}.seed-scope-confirm .button{margin-top:10px}.seed-review-notice{color:#26764e;margin-top:12px}@media(max-width:700px){.seed-review-setup,.seed-review-filters{flex-direction:column;align-items:stretch}.seed-review-item-title small{margin-left:0}}
</style>
